using System;
using System.IO;
using System.Threading.Tasks;
static class UpdateMonitorTests {
 static int count;static void Check(bool ok,string why){if(!ok)throw new Exception(why);}static void Test(string name,Action f){f();count++;Console.WriteLine("通过："+name);}static ReleaseInfo Release(string v){return new ReleaseInfo{Version=v,Notes="测试版本"};}
 static void Main(){Console.OutputEncoding=System.Text.Encoding.UTF8;DateTime time=new DateTime(2026,10,24,0,0,0,DateTimeKind.Utc);
  Test("订单页面就绪后才安排检测，启动延迟不阻塞页面",()=>{using(var m=new UpdateMonitor(()=>Task.FromResult(Release("1.11.0")),()=>time)){Check(!m.ShouldCheckAutomatically(),"尚未启动");m.StartAutomatic();Check(!m.ShouldCheckAutomatically(),"不应立即检查");time=time.AddSeconds(4);Check(!m.ShouldCheckAutomatically(),"过早检查");time=time.AddSeconds(1);Check(m.ShouldCheckAutomatically(),"应在后台开始");}});
  Test("重复就绪通知不会反复延后或重新启动检查",()=>{using(var m=new UpdateMonitor(()=>Task.FromResult(Release("1.11.0")),()=>time)){m.StartAutomatic();time=time.AddSeconds(3);m.StartAutomatic();time=time.AddSeconds(2);Check(m.ShouldCheckAutomatically(),"启动时间被错误重置");}});
  Test("自动和手动检查共用一个进行中的请求",()=>{int calls=0;var gate=new TaskCompletionSource<ReleaseInfo>();using(var m=new UpdateMonitor(()=>{calls++;return gate.Task;},()=>time)){m.StartAutomatic();var a=m.CheckAsync(true);var b=m.CheckAsync(true);Check(Object.ReferenceEquals(a,b)&&calls==1,"重复网络请求");Check(!m.ShouldCheckAutomatically(),"已有请求时不能重复自动检查");gate.SetResult(Release("2.0.0"));a.GetAwaiter().GetResult();Check(m.Status().Available&&m.Status().State=="available","未保存可用更新");}});
  Test("发现新版仅记录提示，打开更新窗口可复用五分钟内结果",()=>{int calls=0,events=0;using(var m=new UpdateMonitor(()=>{calls++;return Task.FromResult(Release("2.0.0"));},()=>time)){m.Changed+=()=>events++;m.CheckAsync(true).GetAwaiter().GetResult();var cached=m.CheckAsync(false).GetAwaiter().GetResult();Check(calls==1&&cached.Version=="2.0.0"&&events==2,"没有复用结果");Check(m.Status().Available,"没有更新提示");m.CheckAsync(true).GetAwaiter().GetResult();Check(calls==2,"手动刷新应重新查询");}});
  Test("成功后四小时检查一次，不频繁访问 GitHub",()=>{using(var m=new UpdateMonitor(()=>Task.FromResult(Release("1.11.0")),()=>time)){m.StartAutomatic();m.CheckAsync(true).GetAwaiter().GetResult();time=time.AddHours(4).AddSeconds(-1);Check(!m.ShouldCheckAutomatically(),"周期过短");time=time.AddSeconds(1);Check(m.ShouldCheckAutomatically(),"到期没有检查");Check(m.Status().State=="current"&&!m.Status().Available,"同版不应提示升级");}});
  Test("网络失败安静保留可用版本，半小时后再试",()=>{bool fail=false;using(var m=new UpdateMonitor(()=>{if(fail)throw new IOException("测试断网");return Task.FromResult(Release("2.0.0"));},()=>time)){m.StartAutomatic();m.CheckAsync(true).GetAwaiter().GetResult();fail=true;try{m.CheckAsync(true).GetAwaiter().GetResult();throw new Exception("预期网络错误");}catch(IOException){}Check(m.Status().Available&&m.Status().State=="error"&&m.Status().Error.Contains("测试断网"),"已知新版提示丢失");time=time.AddMinutes(29);Check(!m.ShouldCheckAutomatically(),"失败时频繁重试");time=time.AddMinutes(1);Check(m.ShouldCheckAutomatically(),"失败后未安排重试");}});
  Test("错误或旧版本不误报新版，之后成功会恢复状态",()=>{bool fail=true;using(var m=new UpdateMonitor(()=>{if(fail)throw new IOException("测试网络");return Task.FromResult(Release("1.10.0"));},()=>time)){try{m.CheckAsync(true).GetAwaiter().GetResult();}catch(IOException){}Check(!m.Status().Available&&m.Status().State=="error","错误被当成有新版");fail=false;m.CheckAsync(true).GetAwaiter().GetResult();Check(m.Status().State=="current"&&!m.Status().Available&&m.Status().Error=="","失败状态未恢复");}});
  Test("关闭窗口后不发送通知，也不再自动检查",()=>{int events=0;var gate=new TaskCompletionSource<ReleaseInfo>();var m=new UpdateMonitor(()=>gate.Task,()=>time);m.Changed+=()=>events++;m.StartAutomatic();var pending=m.CheckAsync(true);Check(events==1,"应进入后台检查");m.Dispose();gate.SetResult(Release("2.0.0"));pending.GetAwaiter().GetResult();Check(events==1&&!m.ShouldCheckAutomatically(),"退出后仍通知或检查");Check(m.CheckAsync(true).GetAwaiter().GetResult()==null,"退出后发起请求");});
  Console.WriteLine("自动检测调度检查共 "+count+" 项通过");
 }
}
